-- ----------------------------
-- Table structure for sys_resource
-- ----------------------------
DROP TABLE IF EXISTS "public"."sys_resource";
CREATE TABLE "public"."sys_resource" (
  "resource_id" int8 NOT NULL,
  "app_code" varchar(100) COLLATE "pg_catalog"."default",
  "resource_code" varchar(300) COLLATE "pg_catalog"."default" NOT NULL,
  "resource_name" varchar(300) COLLATE "pg_catalog"."default" NOT NULL,
  "project_code" varchar(64) COLLATE "pg_catalog"."default",
  "class_name" varchar(100) COLLATE "pg_catalog"."default",
  "method_name" varchar(100) COLLATE "pg_catalog"."default",
  "modular_code" varchar(100) COLLATE "pg_catalog"."default",
  "modular_name" varchar(100) COLLATE "pg_catalog"."default",
  "ip_address" varchar(255) COLLATE "pg_catalog"."default",
  "view_flag" char(1) COLLATE "pg_catalog"."default",
  "url" varchar(300) COLLATE "pg_catalog"."default",
  "http_method" varchar(10) COLLATE "pg_catalog"."default",
  "resource_biz_type" int2 DEFAULT 1,
  "required_login_flag" char(1) COLLATE "pg_catalog"."default",
  "required_permission_flag" char(1) COLLATE "pg_catalog"."default",
  "permission_code" varchar(255) COLLATE "pg_catalog"."default",
  "validate_groups" text COLLATE "pg_catalog"."default",
  "param_field_descriptions" text COLLATE "pg_catalog"."default",
  "response_field_descriptions" text COLLATE "pg_catalog"."default",
  "create_user" int8,
  "create_time" timestamp(6),
  "update_user" int8,
  "update_time" timestamp(6)
)
;
COMMENT ON COLUMN "public"."sys_resource"."resource_id" IS '资源id';
COMMENT ON COLUMN "public"."sys_resource"."app_code" IS '应用编码';
COMMENT ON COLUMN "public"."sys_resource"."resource_code" IS '资源编码';
COMMENT ON COLUMN "public"."sys_resource"."resource_name" IS '资源名称';
COMMENT ON COLUMN "public"."sys_resource"."project_code" IS '项目编码，一般为spring.application.name';
COMMENT ON COLUMN "public"."sys_resource"."class_name" IS '类名称';
COMMENT ON COLUMN "public"."sys_resource"."method_name" IS '方法名称';
COMMENT ON COLUMN "public"."sys_resource"."modular_code" IS '资源模块编码，一般为控制器类名排除Controller';
COMMENT ON COLUMN "public"."sys_resource"."modular_name" IS '资源模块名称，一般为控制器名称';
COMMENT ON COLUMN "public"."sys_resource"."ip_address" IS '资源初始化的服务器ip地址';
COMMENT ON COLUMN "public"."sys_resource"."view_flag" IS '是否是视图类型：Y-是，N-否
如果是视图类型，url需要以 ''/view'' 开头，
视图类型的接口会渲染出html界面，而不是json数据，
视图层一般会在前后端不分离项目出现';
COMMENT ON COLUMN "public"."sys_resource"."url" IS '资源url';
COMMENT ON COLUMN "public"."sys_resource"."http_method" IS 'http请求方法';
COMMENT ON COLUMN "public"."sys_resource"."resource_biz_type" IS '资源的业务类型：1-业务类，2-系统类';
COMMENT ON COLUMN "public"."sys_resource"."required_login_flag" IS '是否需要登录：Y-是，N-否';
COMMENT ON COLUMN "public"."sys_resource"."required_permission_flag" IS '是否需要鉴权：Y-是，N-否';
COMMENT ON COLUMN "public"."sys_resource"."permission_code" IS '需要鉴权的菜单或者功能编码';
COMMENT ON COLUMN "public"."sys_resource"."validate_groups" IS '需要进行参数校验的分组';
COMMENT ON COLUMN "public"."sys_resource"."param_field_descriptions" IS '接口参数的字段描述';
COMMENT ON COLUMN "public"."sys_resource"."response_field_descriptions" IS '接口返回结果的字段描述';
COMMENT ON COLUMN "public"."sys_resource"."create_user" IS '创建人';
COMMENT ON COLUMN "public"."sys_resource"."create_time" IS '创建时间';
COMMENT ON COLUMN "public"."sys_resource"."update_user" IS '更新人';
COMMENT ON COLUMN "public"."sys_resource"."update_time" IS '更新时间';
COMMENT ON TABLE "public"."sys_resource" IS '资源';

-- ----------------------------
-- Table structure for sys_role
-- ----------------------------
DROP TABLE IF EXISTS "public"."sys_role";
CREATE TABLE "public"."sys_role" (
  "role_id" int8 NOT NULL,
  "role_name" varchar(100) COLLATE "pg_catalog"."default" NOT NULL,
  "role_code" varchar(100) COLLATE "pg_catalog"."default" NOT NULL,
  "role_sort" numeric(10,2) NOT NULL,
  "data_scope_type" int2 NOT NULL DEFAULT 1,
  "status_flag" int2 NOT NULL DEFAULT 1,
  "remark" varchar(255) COLLATE "pg_catalog"."default",
  "role_system_flag" char(1) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'N'::bpchar,
  "expand_field" varchar COLLATE "pg_catalog"."default",
  "version_flag" int8,
  "del_flag" char(1) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'N'::bpchar,
  "create_time" timestamp(6),
  "create_user" int8,
  "update_time" timestamp(6),
  "update_user" int8,
  "tenant_id" int8
)
;
COMMENT ON COLUMN "public"."sys_role"."role_id" IS '主键id';
COMMENT ON COLUMN "public"."sys_role"."role_name" IS '角色名称';
COMMENT ON COLUMN "public"."sys_role"."role_code" IS '角色编码';
COMMENT ON COLUMN "public"."sys_role"."role_sort" IS '序号';
COMMENT ON COLUMN "public"."sys_role"."data_scope_type" IS '数据范围类型：10-仅本人数据，20-本部门数据，30-本部门及以下数据，40-指定部门数据，50-全部数据';
COMMENT ON COLUMN "public"."sys_role"."status_flag" IS '状态：1-启用，2-禁用';
COMMENT ON COLUMN "public"."sys_role"."remark" IS '备注';
COMMENT ON COLUMN "public"."sys_role"."role_system_flag" IS '是否是系统角色：Y-是，N-否。系统角色不能删除';
COMMENT ON COLUMN "public"."sys_role"."expand_field" IS '拓展字段';
COMMENT ON COLUMN "public"."sys_role"."version_flag" IS '乐观锁';
COMMENT ON COLUMN "public"."sys_role"."del_flag" IS '删除标记：Y-已删除，N-未删除';
COMMENT ON COLUMN "public"."sys_role"."create_time" IS '创建时间';
COMMENT ON COLUMN "public"."sys_role"."create_user" IS '创建人';
COMMENT ON COLUMN "public"."sys_role"."update_time" IS '更新时间';
COMMENT ON COLUMN "public"."sys_role"."update_user" IS '更新人';
COMMENT ON COLUMN "public"."sys_role"."tenant_id" IS '租户号';
COMMENT ON TABLE "public"."sys_role" IS '系统角色';

