DROP TABLE IF EXISTS "public"."sys_sms";
CREATE TABLE "public"."sys_sms" (
  "sms_id" int8 NOT NULL,
  "phone_number" varchar(11) COLLATE "pg_catalog"."default",
  "validate_code" varchar(100) COLLATE "pg_catalog"."default",
  "template_code" varchar(255) COLLATE "pg_catalog"."default",
  "biz_id" varchar(20) COLLATE "pg_catalog"."default",
  "status_flag" int2,
  "source" int4,
  "invalid_time" timestamp(6),
  "create_time" timestamp(6),
  "create_user" int8,
  "update_time" timestamp(6),
  "update_user" int8
)
;
COMMENT ON COLUMN "public"."sys_sms"."sms_id" IS '主键';
