COMMENT ON COLUMN "public"."sys_sms"."validate_code" IS '短信验证码';
COMMENT ON COLUMN "public"."sys_sms"."template_code" IS '短信模板编号';
COMMENT ON COLUMN "public"."sys_sms"."biz_id" IS '业务id';
COMMENT ON COLUMN "public"."sys_sms"."status_flag" IS '发送状态：1-未发送，2-发送成功，3-发送失败，4-失效';
COMMENT ON COLUMN "public"."sys_sms"."source" IS '来源：1-app，2-pc，3-其他';
COMMENT ON COLUMN "public"."sys_sms"."invalid_time" IS '短信失效截止时间';
COMMENT ON COLUMN "public"."sys_sms"."create_time" IS '创建时间';
COMMENT ON COLUMN "public"."sys_sms"."create_user" IS '创建人';
COMMENT ON COLUMN "public"."sys_sms"."update_time" IS '修改时间';
COMMENT ON COLUMN "public"."sys_sms"."update_user" IS '修改人';
COMMENT ON TABLE "public"."sys_sms" IS '短信发送记录';

